/**
 * The real client entry.
 *
 * app.ts loads this file with a dynamic import so that Lit's hydration support
 * is installed before any Lit code is evaluated. New imports belong here, never
 * in app.ts — see the header of app.ts and BUILD-009.
 */
// Step 2 — client runtime custom elements (router outlet + link)
import '@beatzball/litro/runtime/LitroOutlet.js';
import '@beatzball/litro/runtime/LitroLink.js';

import { enhanceForms } from '@beatzball/litro/actions/form-client';

// Step 3 — routes generated by I-2's page scanner
// routes.generated.ts lives at the project root (not in dist/) so Vite's
// emptyOutDir does not delete it, and it can be re-generated before vite build.
import { routes } from './routes.generated.js';

// Step 4 — initialize the router
// Set .routes synchronously. Module scripts are deferred, so by the time this
// executes the HTML is fully parsed and <litro-outlet> is in the DOM. Setting
// routes here — before Lit's first update microtask fires — ensures
// firstUpdated() sees the real route table, not the empty default.
const outlet = document.querySelector('litro-outlet') as (Element & { routes: unknown }) | null;
if (outlet) {
  outlet.routes = routes;
} else {
  console.warn(
    '[litro] no <litro-outlet> found in the document. ' +
      'Make sure the HTML shell includes <litro-outlet></litro-outlet>.'
  );
}

// Progressive enhancement for light-DOM action forms. Forms inside shadow
// roots attach their own enhancer (see pages/forms.ts) — submit events are
// composed:false and never reach this document-level listener.
enhanceForms();
